svg.metadata:
flowchart TB
  A["ingest: document ID, content and collection"]
  B["Prepare candidate revision; chunk and embed"]
  C["Store candidate vectors; not yet current"]
  D["Conditionally publish the current revision"]
  E["retrieve / ask use published revisions"]
  F["Clean old vectors; repair if needed"]
  X["Preparation / publication fails: report failure, preserve visibility rules"]
  A --> B
  B --> C
  C --> D
  D --> E
  D --> F
  B -->|"failure"| X
  D -->|"conflict / failure"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
  class F pending;
